        for i, ch in enumerate(s):
            for c in range(26):
                pre[c][i + 1] = pre[c][i]
            pre[ord(ch) - 97][i + 1] += 1
        ans = 0
        for i in range(n):
            for j in range(i + 1, n):
                mx, mn = 0, n + 1
                for c in range(26):
                    f = pre[c][j + 1] - pre[c][i]
                    if f > mx:
                        mx = f
                    if 0 < f < mn:
                        mn = f
                ans += mx - mn
        return ans

